WITH f AS (SELECT PGM_SYS_ID, FACILITY_NAME, CITY, STATE FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES
  WHERE PGM_SYS_ID IN ('IALIN0001911300185','IALIN0001911301386','IA0000001907100028','CASJV00006077N0238','NE0000003100100064')),
st AS (SELECT PGM_SYS_ID, COUNT(DISTINCT ACTUAL_END_DATE) TD, COUNT(DISTINCT IFF(AIR_STACK_TEST_STATUS_CODE='FAI',ACTUAL_END_DATE,NULL)) FD FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_STACK_TESTS WHERE ACTUAL_END_DATE BETWEEN '2015-01-01' AND '2025-12-31' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
v AS (SELECT PGM_SYS_ID, COUNT(*) VIOL, COUNT(HPV_DAYZERO_DATE) HPV FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_VIOLATION_HISTORY WHERE COALESCE(HPV_DAYZERO_DATE,EARLIEST_FRV_DETERM_DATE) BETWEEN '2015-01-01' AND '2025-12-31' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1),
fa AS (SELECT PGM_SYS_ID, COUNT(*) FORMAL, SUM(PENALTY_AMOUNT) PEN, LISTAGG(ENF_TYPE_DESC||' '||SETTLEMENT_ENTERED_DATE||' $'||COALESCE(PENALTY_AMOUNT,0),'; ') DET FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS WHERE SETTLEMENT_ENTERED_DATE BETWEEN '2015-01-01' AND '2025-12-31' AND PGM_SYS_ID IN (SELECT PGM_SYS_ID FROM f) GROUP BY 1)
SELECT f.*, TD, FD, VIOL, HPV, FORMAL, PEN, DET FROM f LEFT JOIN st USING(PGM_SYS_ID) LEFT JOIN v USING(PGM_SYS_ID) LEFT JOIN fa USING(PGM_SYS_ID)
